CREATE TABLE manufacturing_specifications (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,name TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('bom','formula')),output_product_id TEXT NOT NULL REFERENCES commerce_products(id),batch_quantity_milli BIGINT NOT NULL CHECK(batch_quantity_milli>0),expected_yield_bps BIGINT NOT NULL CHECK(expected_yield_bps BETWEEN 1 AND 20000),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','rejected','retired')),created_by TEXT NOT NULL,reviewed_by TEXT,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE manufacturing_specification_lines (id TEXT PRIMARY KEY,specification_id TEXT NOT NULL REFERENCES manufacturing_specifications(id),product_id TEXT NOT NULL REFERENCES commerce_products(id),quantity_milli BIGINT NOT NULL CHECK(quantity_milli>0),substitution_group TEXT,ordinal BIGINT NOT NULL,UNIQUE(specification_id,product_id));
CREATE TABLE planning_scenarios (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,branch_id TEXT NOT NULL,warehouse_id TEXT NOT NULL REFERENCES commerce_warehouses(id),specification_id TEXT NOT NULL REFERENCES manufacturing_specifications(id),specification_version BIGINT NOT NULL,demand_quantity_milli BIGINT NOT NULL CHECK(demand_quantity_milli>0),due_date TEXT NOT NULL,capacity_minutes BIGINT NOT NULL CHECK(capacity_minutes>=0),shortages_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'calculated' CHECK(status IN ('calculated','released','cancelled')),created_by TEXT NOT NULL,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE planning_recommendations (id TEXT PRIMARY KEY,scenario_id TEXT NOT NULL UNIQUE REFERENCES planning_scenarios(id),scenario_version BIGINT NOT NULL,recommended_quantity_milli BIGINT NOT NULL CHECK(recommended_quantity_milli>0),required_minutes BIGINT NOT NULL CHECK(required_minutes>=0),feasible_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'proposed' CHECK(status IN ('proposed','approved','rejected')),created_by TEXT NOT NULL,reviewed_by TEXT,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE manufacturing_orders (id TEXT PRIMARY KEY,company_id TEXT NOT NULL,branch_id TEXT NOT NULL,warehouse_id TEXT NOT NULL REFERENCES commerce_warehouses(id),recommendation_id TEXT NOT NULL UNIQUE REFERENCES planning_recommendations(id),specification_id TEXT NOT NULL REFERENCES manufacturing_specifications(id),specification_version BIGINT NOT NULL,planned_quantity_milli BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','reserved','in_progress','awaiting_qc','completed','qc_failed','cancelled')),material_cost_minor BIGINT NOT NULL DEFAULT 0,labor_cost_minor BIGINT NOT NULL DEFAULT 0,overhead_cost_minor BIGINT NOT NULL DEFAULT 0,reported_output_milli BIGINT,reported_scrap_milli BIGINT,created_by TEXT NOT NULL,version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE manufacturing_material_reservations (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES manufacturing_orders(id),warehouse_id TEXT NOT NULL,product_id TEXT NOT NULL,quantity_milli BIGINT NOT NULL CHECK(quantity_milli>0),consumed_milli BIGINT NOT NULL DEFAULT 0,released_milli BIGINT NOT NULL DEFAULT 0,expires_at BIGINT NOT NULL,created_by TEXT NOT NULL,created_at BIGINT NOT NULL,CHECK(consumed_milli+released_milli<=quantity_milli),FOREIGN KEY(warehouse_id,product_id) REFERENCES commerce_stock(warehouse_id,product_id),UNIQUE(order_id,product_id));
CREATE TABLE manufacturing_order_events (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES manufacturing_orders(id),version BIGINT NOT NULL,action TEXT NOT NULL,actor_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL,details_json TEXT NOT NULL,created_at BIGINT NOT NULL,UNIQUE(order_id,version));
CREATE TABLE manufacturing_genealogy (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES manufacturing_orders(id),input_product_id TEXT NOT NULL,output_product_id TEXT NOT NULL,input_quantity_milli BIGINT NOT NULL,output_quantity_milli BIGINT NOT NULL,source_order_version BIGINT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE manufacturing_cost_snapshots (id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES manufacturing_orders(id),source_order_version BIGINT NOT NULL,material_minor BIGINT NOT NULL,labor_minor BIGINT NOT NULL,overhead_minor BIGINT NOT NULL,total_minor BIGINT NOT NULL,output_quantity_milli BIGINT NOT NULL,created_at BIGINT NOT NULL);
CREATE OR REPLACE VIEW inventory_active_reservations AS SELECT warehouse_id,product_id,quantity_milli,'pos'::text source_kind,fulfillment_id source_id,NULL::text order_line_id FROM pos_reservations UNION ALL SELECT warehouse_id,product_id,quantity_milli-consumed_milli-released_milli,'sales',id,order_line_id FROM inventory_order_reservations WHERE quantity_milli>consumed_milli+released_milli AND expires_at>floor(extract(epoch FROM statement_timestamp())*1000)::bigint UNION ALL SELECT warehouse_id,product_id,quantity_milli-consumed_milli-released_milli,'field_service',id,NULL::text FROM field_service_part_reservations WHERE quantity_milli>consumed_milli+released_milli AND expires_at>floor(extract(epoch FROM statement_timestamp())*1000)::bigint UNION ALL SELECT warehouse_id,product_id,quantity_milli-consumed_milli-released_milli,'manufacturing',id,NULL::text FROM manufacturing_material_reservations WHERE quantity_milli>consumed_milli+released_milli AND expires_at>floor(extract(epoch FROM statement_timestamp())*1000)::bigint;
CREATE TRIGGER manufacturing_reservation_changed AFTER INSERT OR UPDATE OR DELETE ON manufacturing_material_reservations FOR EACH ROW EXECUTE FUNCTION inventory_reservation_changed();
CREATE FUNCTION manufacturing_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME IN ('manufacturing_order_events','manufacturing_genealogy','manufacturing_cost_snapshots') OR TG_OP='DELETE' THEN RAISE EXCEPTION 'MANUFACTURING_HISTORY_IMMUTABLE' USING ERRCODE='23514'; END IF; IF TG_TABLE_NAME='manufacturing_specifications' THEN IF (NEW.id,NEW.company_id,NEW.mode,NEW.output_product_id,NEW.batch_quantity_milli,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.company_id,OLD.mode,OLD.output_product_id,OLD.batch_quantity_milli,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'MANUFACTURING_SPEC_SOURCE_IMMUTABLE' USING ERRCODE='23514'; END IF; ELSIF TG_TABLE_NAME='planning_scenarios' THEN IF (NEW.id,NEW.company_id,NEW.branch_id,NEW.warehouse_id,NEW.specification_id,NEW.specification_version,NEW.demand_quantity_milli,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.company_id,OLD.branch_id,OLD.warehouse_id,OLD.specification_id,OLD.specification_version,OLD.demand_quantity_milli,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'PLANNING_SOURCE_IMMUTABLE' USING ERRCODE='23514'; END IF; ELSIF TG_TABLE_NAME='manufacturing_orders' THEN IF (NEW.id,NEW.company_id,NEW.branch_id,NEW.warehouse_id,NEW.recommendation_id,NEW.specification_id,NEW.specification_version,NEW.planned_quantity_milli,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.company_id,OLD.branch_id,OLD.warehouse_id,OLD.recommendation_id,OLD.specification_id,OLD.specification_version,OLD.planned_quantity_milli,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'MANUFACTURING_ORDER_SOURCE_IMMUTABLE' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['manufacturing_specifications','planning_scenarios','manufacturing_orders','manufacturing_order_events','manufacturing_genealogy','manufacturing_cost_snapshots'] LOOP EXECUTE format('CREATE TRIGGER manufacturing_guard BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION manufacturing_guard()',t);END LOOP;END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['manufacturing_specifications','planning_scenarios','planning_recommendations','manufacturing_orders','manufacturing_material_reservations'] LOOP INSERT INTO work_cache_revisions(table_name) VALUES(t) ON CONFLICT DO NOTHING;EXECUTE format('CREATE TRIGGER work_cache_change AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION work_cache_changed()',t);EXECUTE format('CREATE TRIGGER work_cache_truncate AFTER TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION work_cache_changed()',t);END LOOP;END $$;
